package com.bplus.share;
import org.json.*;import java.nio.charset.StandardCharsets;import java.security.*;import javax.crypto.*;import javax.crypto.spec.*;
public final class UnpairWire{
 static byte[] utf(String s){return s.getBytes(StandardCharsets.UTF_8);}public static String hex(byte[] b){StringBuilder s=new StringBuilder();for(byte x:b)s.append(String.format(java.util.Locale.US,"%02x",x&255));return s.toString();}public static byte[] digest(String s)throws Exception{return MessageDigest.getInstance("SHA-256").digest(utf(s));}
 private static String ordered(String local,String token,String remote,String other){return local.compareTo(remote)<0?local+"\n"+token+"\n"+remote+"\n"+other:remote+"\n"+other+"\n"+local+"\n"+token;}
 public static byte[] key(String a,String at,String b,String bt)throws Exception{return digest("bplus-pair-key-v1\n"+ordered(a,at,b,bt));}public static String legacy(String a,String at,String b,String bt)throws Exception{return hex(digest("bplus-pair-epoch-v1\n"+ordered(a,at,b,bt)));}public static String nearby(String request,String secret)throws Exception{return hex(digest("bplus-pair-epoch-v1\n"+request+"\n"+secret));}
 public static String mac(JSONObject n,byte[] key,boolean ack)throws Exception{if(n.optInt("v")!=1||!n.optString("epoch").matches("[a-f0-9]{64}")||!n.optString("event").matches("[a-f0-9]{64}"))throw new Exception("Invalid notice");String body=(ack?"bplus-unpair-ack-v1":"bplus-unpair-v1")+"\n"+n.getString("from")+"\n"+n.getString("to")+"\n"+n.getString("epoch")+"\n"+n.getString("event");Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(key,"HmacSHA256"));return hex(m.doFinal(utf(body)));}
 public static boolean verify(JSONObject n,byte[] key,boolean ack)throws Exception{return (!ack||n.optString("status").equals("unpaired"))&&MessageDigest.isEqual(utf(mac(n,key,ack)),utf(n.optString("mac")));}
 public static JSONObject ack(JSONObject n,byte[] key)throws Exception{JSONObject a=new JSONObject().put("v",1).put("status","unpaired").put("from",n.getString("to")).put("to",n.getString("from")).put("epoch",n.getString("epoch")).put("event",n.getString("event"));return a.put("mac",mac(a,key,true));}
}
